Q: new line doesn&#39;t go to the next line A: <p>Problem is poor choice of symbol names and poor design. This makes code hard to read and understand. This is a reason you had problem addressing issue by yourself.</p>
<p>Take a look on this appraoch:</p>
<pre class="lang-cpp prettyprint-override"><code>using VgaBuffer = std::mdspan&lt;
    std::uint8_t,
    std::extents&lt;std::size_t, 25, 80, 2&gt;&gt;;

constexpr std::uint8_t WhiteTextOnBlack = 0x07;

class ScreenWriter {
public:
    ScreenWriter(VgaBuffer buf)
        : out { buf }
    {
    }

    void print(std::string_view s)
    {
        for (auto ch : s) {
            if (isControllChar(ch)) {
                handleControl(ch);
            } else {
                addChar(ch);
            }
        }
    }

private:
    static constexpr bool isControllChar(char ch) noexcept
    {
        return ch &gt;= 0 &amp;&amp; ch &lt; ' ';
    }

    void addChar(char ch)
    {
        if (col &lt; 80) {
            out[row, col, 0] = ch;
            out[row, col, 1] = def_attr;
            ++col;
        }
    }

    void handleControl(char ch)
    {
        switch (ch) {
        case '\n':
            nextLine();
            break;
        case '\r':
            beginOfLine();
            break;
        case '\t':
            tab();
            break;
            // TODO: other control characters:
        }
    }

    void nextLine()
    {
        ++row;
        beginOfLine();
    }

    void beginOfLine()
    {
        col = 0;
    }

    void tab()
    {
        addChar(' ');
        addChar(' ');
        addChar(' ');
        addChar(' ');
    }

private:
    VgaBuffer out;
    size_t col = 0;
    size_t row = 0;
    std::uint8_t def_attr = WhiteTextOnBlack;
};
</code></pre>
<p>This is easy to read and easy to test.</p>
